export const log = (e, msg) => logSub(e, msg)  

export const logFocus = (e) => logSub(e,'FOCUS')  

export const logClick = (e) => logSub(e,'CLICK')  

export const logInput = (e) => logSub(e,'INPUT')  

export const logAll = (e) => logSub(e,'ALL')  

export const logModel = (e) => logSub(e,'MODEL-VALUE')  

export const logPlain = (e) => logSub(e,'PLAIN')  
 
export const logCustomEvent = (e) => logSub(e,'CustomEvent')  
  
export const logElement = (e) => logSub(e,'ELEMENT')  
  
export const logNamedElement = (e) => logSub(e,'NAMED-ELEMENT')  
  
export const logButton = (e) => logSub(e,'BUTTON')  
  
export const logIcon = (e) => logSub(e,'ICON')  
  
export const logInline = (val, e) => logSub(e,'INLINE *** ', val)  
 

export const logSub = (e, msg = 'BASE') => {
    
  if (e?._isCustomEvent){
    console.info(`LOG# - ${msg} | Emitter: ${e?.emitter } | Element: ${e?.id } | Value:${e.modelValue}`)  
    console.warn(`LOG# - CustomEvent`, e)
    // console.info(`LOG# -   MODEL`, {...e.model})
    // console.info(`LOG# -   SCHEMA`, {...e.schema})
    // console.info(`LOG# -   OBJ`, {...e.obj})
    
  } else {
    
    if (e?.target){
      console.info(`LOG# - ${msg} | ${e?.type} | Native Event:`, e?.target);
    } else {
      console.info(`LOG# - ${msg} | Emitter: update:modelValue | ### Value:${e}`)
    }
  
  }

  return undefined // any returned value in inline events change the value of the element
}
